pages/custom/category/autoselect-assist:
---
category:
    products:
        limit: 250
---
{{inject "categoryProductsPerPage" theme_settings.categorypage_products_per_page}}
{{#partial "head"}}
<link rel="preload" href="{{cdn 'assets/dist/theme-bundle.chunk.category.js' resourceHint='preload' as='script'}}"
    as="script">
{{#if pagination.category.previous}}
<link rel="prev" href="{{{pagination.category.previous}}}">
{{/if}}
{{#if pagination.category.next}}
<link rel="next" href="{{{pagination.category.next}}}">
{{/if}}
{{/partial}}

{{#partial "page"}}

<div class="plp-page">
    <div class="plp-page-header" id="page-sidebar-header">
        {{> components/common/breadcrumbs breadcrumbs=breadcrumbs}}
        {{#unless theme_settings.hide_category_page_heading }}
        {{/unless}}

        {{#if category.image}}
        <div class="plp-main-image _category">
            {{> components/common/responsive-img
            image=category.image
            fallback_size=theme_settings.zoom_size
            lazyload=theme_settings.lazyload_mode
            class="category-header-image"
            }}
        </div>
        {{/if}}

        {{{region name="category_below_header"}}}
    </div>

    <main class="plp-page-main" id="product-listing-container">
        <div class="page-content page-content--centered"></div>
        <style>
            /* Custom styles for the quiz */
            .question,
            .result {
                font-weight: bold;
                margin: 20px 0;
            }

            .option {
                cursor: pointer;
                text-transform: capitalize;
            }

            @media screen and (max-width: 801px) {
                .option {
                    width: 90%
                }
            }

            .option.is-selected {
                background-color: #fff;
                border-color: #dc3522;
                color: #dc3522;
            }

            .option.is-selected:hover {
                background-color: #222;
                border-color: #dc3522;
            }

            .multi-select-hint {
                color: #555;
                font-size: 14px;
                margin: 0 0 8px;
            }

            #quiz-container {
                border: 1px solid #ebe8e8;
                margin: 0 auto 24px;
                width: 100%;
            }

            #options-container {
                font-size: 16px;
                margin: 0 auto;
                width: 100%;
            }

            .quiz-layout {
                display: grid;
                gap: 24px;
                grid-template-columns: minmax(0, 1fr) 280px;
                align-items: start;
            }

            .quiz-main {
                min-width: 0;
            }

            .quiz-summary {
                align-self: start;
                background-color: #fafafa;
                border: 1px solid #e5e5e5;
                border-radius: 6px;
                padding: 12px;
                position: sticky;
                top: 16px;
            }

            .quiz-summary-panel {
                position: sticky;
                top: 16px;
                align-self: start;
            }

            .quiz-summary-toggle {
                width: 100%;
                margin-bottom: 8px;
            }

            .quiz-summary.is-collapsed {
                display: none;
            }

            .quiz-summary-title {
                font-size: 16px;
                margin: 0 0 8px;
            }

            .quiz-summary-list {
                list-style: none;
                margin: 0;
                padding: 0;
                display: grid;
                gap: 8px;
            }

            .quiz-summary-item {
                display: flex;
                flex-direction: column;
                gap: 4px;
            }

            .quiz-summary-label {
                font-weight: 600;
            }

            .quiz-summary-value {
                color: #444;
            }

            .quiz-summary-empty {
                color: #666;
                font-size: 14px;
            }

            .card-figcaption-button {
                width: 100%;
            }

            #result-container {
                text-align: center;
            }

            #progress-bar-container {
                background-color: #e0e0e0;
                border-radius: 8px;
                height: 16px;
                margin-bottom: 16px;
                overflow: hidden;
                width: 100%;
            }

            #progress-bar {
                background-color: #4CAF50;
                height: 100%;
                transition: width 0.3s ease-in-out;
                width: 0%;
            }

            #quiz-products-source {
                display: none;
            }

            .pagination {
                display: none;
            }

            .budget-range-input {
                width: 50%;
                margin-right: 8px;
            }

            .quiz-actions {
                display: flex;
                gap: 12px;
                margin-top: 12px;
            }

            .quiz-actions--full {
                grid-column: 1 / -1;
                width: 100%;
            }

            .quiz-actions .quiz-continue {
                background-color: #000;
                border-color: #000;
                color: #fff;
                width: auto;
            }

            .quiz-actions .quiz-continue:hover,
            .quiz-actions .quiz-continue:focus {
                background-color: #222;
                border-color: #222;
                color: #fff;
            }

            .quiz-continue {
                grid-column: 1 / -1;
                justify-self: start;
                margin-top: 8px;
                width: auto;
            }

            .quiz .card-footer {
                flex-wrap: nowrap;
            }

            .quiz .productGrid {
                overflow: hidden;
                gap: 16px;
            }

            @media screen and (min-width: 1262px) {
                .quiz .productGrid {
                    grid-template-columns: repeat(3, 1fr);
                }
            }

            @media screen and (max-width: 1261px) {
                .quiz .productGrid {
                    grid-template-columns: repeat(2, 1fr);
                }
            }

            @media screen and (max-width: 801px) {
                .quiz .productGrid {
                    grid-template-columns: 1fr;
                    justify-items: center;
                }

                .quiz .productGrid>.product {
                    width: 100%;
                }

                .quiz .card-footer {
                    flex-wrap: wrap;
                }
            }

            @media screen and (max-width: 1024px) {
                .quiz-layout {
                    grid-template-columns: 1fr;
                }

                .quiz-summary {
                    position: static;
                    top: auto;
                }
            }

            .port-counts {
                display: flex;
                flex-wrap: wrap;
            }

            .port-count-row {
                padding: 20px;
            }

            /*Selection Assistance Form Styles*/
            .selectAssist * {
                transition: .15s;
            }

            .selectAssist {
                background-color: #f8f8f8;
                border: 1px solid rgba(0, 0, 0, .05);
                border-radius: 2px;
                box-shadow: 0 1px 2px rgba(34, 34, 34, .13);
                margin: 0 -1.5rem;

            }

            @media (min-width:551px) {
                .selectAssist {
                    margin: 0 0;
                }
            }

            .infusion-field {
                float: none;
                width: auto;
                margin-top: 16px;
            }

            .infusion-option {
                display: block;
            }

            .infusion-field label {
                opacity: 0.75;
            }

            .infusion-field label:hover,
            .infusion-field input:checked+label {
                opacity: 1;
            }

            .infusion-radio {
                display: block;
                margin-top: 0.5em;
            }

            .infusion-field label {
                display: inline-block;
                float: none;
                font-weight: normal;
                margin: 6px 12px 6px 0;
                width: auto;
            }

            .infusion-field textarea {
                border: 1px solid #ccc;
                margin-bottom: 12px;
                width: 100%;
            }

            .infusion-field textarea:focus {
                border: 1px solid #999;
            }

            .infusion-field select {
                display: block;
                border: 1px solid #ccc;
            }

            .selectAssist .infusion-field input[type="text"] {
                display: block;
                width: 66%;
                min-width: 192px;
                border: 1px solid #ccc;
            }

            .selectAssist .infusion-field input[type="text"]:focus {
                border: 1px solid #999;
            }

            .infusion-field input[type="radio"] {
                display: none;
            }

            .infusion-field input[type="radio"]+label span {
                border: 1px solid #999;
                border-radius: 12px;
                display: inline-block;
                height: 12px;
                margin-bottom: 2px;
                margin-right: 0.5em;
                vertical-align: middle;
                width: 12px;
            }

            .infusion-field input[type="radio"]:disabled+label,
            .infusion-field input[type="checkbox"]:disabled+label {
                opacity: 0.5;
            }

            .infusion-field input[type="radio"]:checked+label,
            .infusion-field input[type="checkbox"]:checked+label {
                opacity: 1;
            }

            .infusion-field input[type="radio"]:checked+label span {
                background-image: radial-gradient(#dc3522 4px, transparent 4px);
            }

            .infusion-captcha,
            .infusion-submit {
                float: none;
            }

            .field1 .infusion-submit input {
                background: #dc3522;
                border: none;
                border-radius: 3px;
                color: #fff;
                cursor: pointer;
                font-display: swap;
                font-family: 'Roboto';
                margin-top: 1rem;
                padding: 1em;
                width: 100%;
            }

            .field1 .infusion-submit input:hover {
                background: #c4301f;
            }

            .choices input:checked+label {
                background: #dcdcdc;
                border: 1px solid #777777;
                border-bottom: none;
                padding: 8px 16px 2px 16px;
                margin: 0 16px 16px 0;
            }

            .control:checked~.conditional {
                background: #ebe8e8;
                box-shadow: 0 2px 4px #dedcdc;
                clip: auto;
                display: block;
                height: auto;
                margin: 16px 0;
                overflow: visible;
                padding: 16px;
                position: static;
            }

            .control:checked~.conditional:before {
                border-bottom-color: #e0e0e0;
                border-color: transparent;
                border-style: solid outset solid solid;
                border-width: 10px;
                content: ' ';
                display: block;
                height: 0;
                left: 0;
                margin-bottom: -16px;
                position: relative;
                top: -35px;
                width: 0;
            }

            .control:not(:checked)~.conditional,
            #touchscreenYes:not(:checked)~.conditional,
            #gobiYes:not(:checked)~.conditional,
            #opticalYes:not(:checked)~.conditional,
            #inf_custom_usevehicle_Yes:not(:checked)~.conditional,
            #needMountYes:not(:checked)~.conditional {
                border: 0;
                clip: rect(0 0 0 0);
                height: 1px;
                margin: -1px;
                overflow: hidden;
                padding: 0;
                position: absolute;
                width: 1px;
            }

            .formSection {
                border-bottom: 1px solid #ddd;
                margin-bottom: 2em;
            }

            .formSection h2 {
                margin-left: 12px;
                padding: 12px;
            }

            .field1 {
                clear: left;
                display: block;
                margin: 8px;
                padding: 16px;
            }

            .field1>label {
                font-size: 1.25em;
                opacity: 1;
            }

            label.rectangle {
                display: block;
                float: left;
                margin: 0 5px 12px 0;
                opacity: 1;
                position: relative;
            }

            .rectangle input {
                position: absolute;
                z-index: 1;
                width: 100%;
                height: 100%;
                cursor: pointer;
                opacity: 0;
            }

            .rectangle-text {
                display: block;
                padding: 1em;
                margin: 0 .5em 0 0;
                text-align: center;
                background: #dedcdc;
                opacity: 0.75;
            }

            .rectangle input:hover+.rectangle-text {
                background: #ccc;
            }

            .rectangle input[type=checkbox]:checked+.rectangle-text {
                background: #dc3522;
                color: #fff;
                opacity: 1;
            }

            .tenscale {
                display: flex;
                justify-content: space-between;
                margin-bottom: 24px;
                position: relative;
            }

            .tenscale input {
                display: block !important;
                opacity: 0;
            }

            .tenscale label {
                display: inline-block;
                opacity: 1;
            }

            .tenscale label input[type="radio"]:checked+span {
                background: #dc3522;
                color: #fff;
            }

            .tenscale label span {
                display: block;
                height: 26px;
                width: 26px;
                text-align: center;
                border: 1px solid #999;
                border-radius: 13px;
                cursor: pointer;
            }

            .tenscale label span:hover {
                background: #ccc;
            }

            .elab {
                border: 0;
                clip: rect(0 0 0 0);
                height: 1px;
                width: 100%;
                margin: -1px;
                overflow: hidden;
                padding: 0;
                position: absolute;
                opacity: 0;
            }

            #inf_option_Onascaleof1to10howmuchphysicalabusewillthisToughbookhavetoendure_1123:checked~.elab,
            #inf_option_Onascaleof1to10howmuchphysicalabusewillthisToughbookhavetoendure_1125:checked~.elab,
            #inf_option_Onascaleof1to10howmuchphysicalabusewillthisToughbookhavetoendure_1127:checked~.elab,
            #inf_option_Onascaleof1to10howmuchphysicalabusewillthisToughbookhavetoendure_1129:checked~.elab,
            #inf_option_Onascaleof1to10howmuchphysicalabusewillthisToughbookhavetoendure_1131:checked~.elab,
            #inf_option_Onascaleof1to10howmuchphysicalabusewillthisToughbookhavetoendure_1133:checked~.elab,
            #inf_option_Onascaleof1to10howmuchphysicalabusewillthisToughbookhavetoendure_1135:checked~.elab,
            #inf_option_Onascaleof1to10howmuchphysicalabusewillthisToughbookhavetoendure_1137:checked~.elab,
            #inf_option_Onascaleof1to10howmuchphysicalabusewillthisToughbookhavetoendure_1139:checked~.elab,
            #inf_option_Onascaleof1to10howmuchphysicalabusewillthisToughbookhavetoendure_1141:checked~.elab {
                clip: auto;
                height: auto;
                width: 100%;
                margin: 16px 0;
                overflow: visible;
                position: absolute;
                left: 0;
                text-align: center;
                opacity: 1;
                color: #dc3522;
            }

            @media only screen and (max-width: 700px) {
                .tenscale {
                    flex-direction: column;
                }

                .tenscale input {
                    display: block !important;
                    opacity: 0;
                }

                .tenscale label span {
                    cursor: none;
                }

                #inf_option_Onascaleof1to10howmuchphysicalabusewillthisToughbookhavetoendure_1123:checked~.elab,
                #inf_option_Onascaleof1to10howmuchphysicalabusewillthisToughbookhavetoendure_1125:checked~.elab,
                #inf_option_Onascaleof1to10howmuchphysicalabusewillthisToughbookhavetoendure_1127:checked~.elab,
                #inf_option_Onascaleof1to10howmuchphysicalabusewillthisToughbookhavetoendure_1129:checked~.elab,
                #inf_option_Onascaleof1to10howmuchphysicalabusewillthisToughbookhavetoendure_1131:checked~.elab,
                #inf_option_Onascaleof1to10howmuchphysicalabusewillthisToughbookhavetoendure_1133:checked~.elab,
                #inf_option_Onascaleof1to10howmuchphysicalabusewillthisToughbookhavetoendure_1135:checked~.elab,
                #inf_option_Onascaleof1to10howmuchphysicalabusewillthisToughbookhavetoendure_1137:checked~.elab,
                #inf_option_Onascaleof1to10howmuchphysicalabusewillthisToughbookhavetoendure_1139:checked~.elab,
                #inf_option_Onascaleof1to10howmuchphysicalabusewillthisToughbookhavetoendure_1141:checked~.elab {
                    margin-top: -24px;
                    position: absolute;
                    left: 10px;
                    text-align: center;
                    opacity: 1;
                    color: #dc3522;
                }
            }

            .selectAssist .grecaptcha-badge {
                display: none !important;
            }
        </style>
        <div class="main-content">
            <div class="dual-form-container">
                <h2>Rugged Computer Selection Assistance</h2>
                <div>Need help choosing the right rugged computer? We offer two simple ways to get expert
                    recommendations tailored to your needs:</div>
                <ul>
                    <li>Use our Auto Selection Assistance tool. This interactive quiz guides you through your
                        requirements and instantly matches you with the best rugged computer options from our inventory.
                    </li>
                    <li>Fill out the classic Bob Johnson's Selection Assistance Form. Our team will review your needs
                        and reach out within 1-2 business days with personalized recommendations.</li>
                </ul>
                <p>You can further customize your rugged computer with a variety of options, including extended warranties, solid state drives (SSDs), additional RAM, and integrated mobile data cards. These upgrades are available on the option lists for most units, allowing you to tailor your selection to your exact needs.</p>
                <div class="support-switcher"><label><input type="radio" name="formChoice" value="tech" /> Auto Selection Assistance</label> <label><input type="radio" name="formChoice"
                            value="repairs" /> Selection Assistance Form</label></div>
                <div class="form-wrapper">
                    <div class="form-panel is-hidden" data-form="tech">
                        <div class="quiz">
                            <div id="quiz-container">
                                <div id="progress-bar-container">
                                    <div id="progress-bar"></div>
                                </div>
                                <div class="quiz-layout">
                                    <div class="quiz-main">
                                        <div id="question-container" class="question"></div>
                                        <ul id="options-container" class="productGrid"></ul>
                                    </div>
                                    <aside class="quiz-summary-panel">
                                        <button type="button" id="quiz-summary-toggle" class="button button--secondary quiz-summary-toggle" aria-expanded="false">
                                            View selections
                                        </button>
                                        <div id="quiz-summary" class="quiz-summary is-collapsed"></div>
                                    </aside>
                                </div>
                            </div>
                            <ul id="result-container" class="result"></ul>
                        </div>
                        <p>If you do not get any options, odds are we do not have a computer of that configuration. Please complete our form so one of our rugged computer experts can assist you further.</p>
                        <div id="quiz-products-source">
                            {{> components/category/product-listing}}
                        </div>
                    </div>
                    <div class="form-panel is-hidden" data-form="repairs">
                        <p>Not sure which rugged computer is right for you? Answer a few questions for us and a member
                            of our staff will
                            help you figure out a solution. The more information you can provide, the better, but if you
                            are unsure of
                            how to answer a question, feel free to skip it.</p>
                        <form accept-charset="UTF-8"
                            action="https://gc200.infusionsoft.com/app/form/process/8a3ea6422a30268cd397383fd61af459"
                            class="infusion-form selectAssist" method="POST">
                            <input name="inf_form_xid" type="hidden" value="8a3ea6422a30268cd397383fd61af459" />
                            <input name="inf_form_name" type="hidden" value="Selection Assistance 2.0" />
                            <input name="infusionsoft_version" type="hidden" value="1.55.0.65" />
                            <div class="formSection">

                                <div class="infusion-field field1">
                                    <label for="inf_option_Doyouwanttoknowaboutnewcomputersorrefurbished">Do you want to
                                        know about new
                                        computers or refurbished?</label>
                                    <div class="infusion-radio">
                                        <span class="infusion-option">
                                            <input id="inf_option_Doyouwanttoknowaboutnewcomputersorrefurbished_4672"
                                                name="inf_option_Doyouwanttoknowaboutnewcomputersorrefurbished"
                                                type="radio" value="4672" />
                                            <label
                                                for="inf_option_Doyouwanttoknowaboutnewcomputersorrefurbished_4672"><span></span>New
                                                computers only</label>
                                        </span>
                                        <span class="infusion-option">
                                            <input id="inf_option_Doyouwanttoknowaboutnewcomputersorrefurbished_4674"
                                                name="inf_option_Doyouwanttoknowaboutnewcomputersorrefurbished"
                                                type="radio" value="4674" />
                                            <label
                                                for="inf_option_Doyouwanttoknowaboutnewcomputersorrefurbished_4674"><span></span>Refurbished
                                                computers only</label>
                                        </span>
                                        <span class="infusion-option">
                                            <input id="inf_option_Doyouwanttoknowaboutnewcomputersorrefurbished_4676"
                                                name="inf_option_Doyouwanttoknowaboutnewcomputersorrefurbished"
                                                type="radio" value="4676" />
                                            <label
                                                for="inf_option_Doyouwanttoknowaboutnewcomputersorrefurbished_4676"><span></span>Either/Both/No
                                                preference</label>
                                        </span>
                                    </div>
                                </div>
                                <div class="infusion-field field1">
                                    <label for="inf_option_Whattypeofcomputerareyoulookingfor">What type of computer are
                                        you looking
                                        for?</label>
                                    <div class="infusion-radio">
                                        <span class="infusion-option">
                                            <input id="inf_option_Whattypeofcomputerareyoulookingfor_4678"
                                                name="inf_option_Whattypeofcomputerareyoulookingfor" type="radio"
                                                value="4678" />
                                            <label
                                                for="inf_option_Whattypeofcomputerareyoulookingfor_4678"><span></span>Laptop</label>
                                        </span>
                                        <span class="infusion-option">
                                            <input id="inf_option_Whattypeofcomputerareyoulookingfor_4680"
                                                name="inf_option_Whattypeofcomputerareyoulookingfor" type="radio"
                                                value="4680" />
                                            <label
                                                for="inf_option_Whattypeofcomputerareyoulookingfor_4680"><span></span>Tablet</label>
                                        </span>
                                        <span class="infusion-option">
                                            <input id="inf_option_Whattypeofcomputerareyoulookingfor_4682"
                                                name="inf_option_Whattypeofcomputerareyoulookingfor" type="radio"
                                                value="4682" />
                                            <label
                                                for="inf_option_Whattypeofcomputerareyoulookingfor_4682"><span></span>Not
                                                sure/No
                                                preference</label>
                                        </span>
                                    </div>
                                </div>

                                <div class="infusion-field field1">
                                    <label for="inf_option_Willyoubeusingthiscomputerforyourjob">Will you be using this
                                        computer for
                                        your job?</label>

                                    <div class="infusion-radio">
                                        <input id="inf_option_Willyoubeusingthiscomputerforyourjob_1069"
                                            name="inf_option_Willyoubeusingthiscomputerforyourjob" type="radio"
                                            value="1069" class="control" />
                                        <label
                                            for="inf_option_Willyoubeusingthiscomputerforyourjob_1069"><span></span>Yes</label>

                                        <div class="conditional">
                                            <label for="inf_custom_Industry1">In what industry do you work?</label>
                                            <select id="inf_custom_Industry1" class="form-select"
                                                name="inf_custom_Industry1">
                                                <option value="">Please select one</option>
                                                <option value="Law Enforcement">Law Enforcement</option>
                                                <option value="Fire">Fire</option>
                                                <option value="EMS">EMS</option>
                                                <option value="Defense">Defense</option>
                                                <option value="Construction">Construction</option>
                                                <option value="Health Care">Health Care</option>
                                                <option value="Automotive">Automotive</option>
                                                <option value="Aviation">Aviation</option>
                                                <option value="Logistics">Logistics</option>
                                                <option value="Government">Government</option>
                                                <option value="Telecommunications">Telecommunications</option>
                                                <option value="Oil & Gas Utility">Oil & Gas Utility</option>
                                                <option value="Electric Utility">Electric Utility</option>
                                                <option value="Water Utility">Water Utility</option>
                                                <option value="Other">Other</option>
                                            </select>
                                            <div class="infusion-field conditional" style="margin-top:4px;">
                                                <label for="inf_custom_Ifotherpleasespecify">If other, please
                                                    specify</label>
                                                <input class="infusion-field-input-container form-input"
                                                    id="inf_custom_Ifotherpleasespecify"
                                                    name="inf_custom_Ifotherpleasespecify" type="text" />
                                            </div>
                                            <div class="infusion-field">
                                                <label for="inf_field_JobTitle">What is your position / job
                                                    title?</label>
                                                <input class="infusion-field-input-container form-input"
                                                    id="inf_field_JobTitle" name="inf_field_JobTitle" type="text" />
                                            </div>
                                        </div>

                                        <div>
                                            <input id="inf_option_Willyoubeusingthiscomputerforyourjob_1071"
                                                name="inf_option_Willyoubeusingthiscomputerforyourjob" type="radio"
                                                value="1071" />
                                            <label
                                                for="inf_option_Willyoubeusingthiscomputerforyourjob_1071"><span></span>No</label>
                                        </div>
                                    </div>


                                </div>
                            </div>
                            <div class="formSection">
                                <h2>Environmental Conditions</h2>
