<script>
    const formChoiceInputs = document.querySelectorAll('input[name="formChoice"]');

    function syncPanels(choice) {
        document.querySelectorAll('.form-panel').forEach(panel => {
            panel.classList.toggle('is-hidden', panel.dataset.form !== choice);
        });
    }

    formChoiceInputs.forEach(input => {
        input.addEventListener('change', () => {
            syncPanels(input.value);
        });
    });

    // Ensure neither form shows on page open
    document.addEventListener('DOMContentLoaded', () => {
        formChoiceInputs.forEach(input => { input.checked = false; });
        document.querySelectorAll('.form-panel').forEach(panel => panel.classList.add('is-hidden'));
    });
</script>

